<article class="product-card"><a class="product-image" href="{{ route('product.show',$product->slug) }}">@if($product->main_image_path)<img loading="lazy" src="{{ asset('storage/'.$product->main_image_path) }}" alt="{{ $product->name_bn ?: $product->name_en }}">@else<div class="image-placeholder">ছবি যোগ করুন</div>@endif @if($product->compare_price && $product->compare_price>$product->price)<span class="sale-badge">অফার</span>@endif</a><div class="product-body"><a class="product-name" href="{{ route('product.show',$product->slug) }}">{{ $product->name_bn ?: $product->name_en }}</a><div class="price-row"><strong>৳{{ number_format((float)$product->price,2) }}</strong>@if($product->compare_price)<del>৳{{ number_format((float)$product->compare_price,2) }}</del>@endif</div><form action="{{ route('cart.add',$product) }}" method="post" class="track-form quick-order-form" data-meta-event="AddToCart" data-content-id="{{ $product->sku }}" data-value="{{ $product->price }}">@csrf<input type="hidden" name="quantity" value="1"><button class="btn primary full">অর্ডার করুন</button></form></div></article>
